<script setup lang="ts">import{onMounted,ref}from'vue';import{BellRing}from'@lucide/vue';import{api}from'../services/api';import type{Alert}from'../types';const alerts=ref<Alert[]>([]);onMounted(async()=>{try{alerts.value=(await api.listAlerts()).items}catch{alerts.value=[]}})</script><template><section><div class="page-title"><div><h1>告警中心</h1><p>集中查看校准逾期、状态阻断和证书到期提醒</p></div></div><div class="alert-list"><article v-for="alert in alerts" :key="alert.id" :class="`alert-${alert.severity}`"><BellRing :size="20"/><div><strong>{{alert.title}}</strong><p>{{alert.message}}</p><small>{{new Date(alert.created_at).toLocaleString('zh-CN')}}</small></div><button class="quiet">确认</button></article></div><div v-if="!alerts.length" class="empty-state"><BellRing :size="42"/><h2>没有未确认告警</h2><p>定时扫描产生的本地提醒将在这里显示。</p></div></section></template>

